    if (path == null || path.isEmpty()) {
        return new ArrayList<>();
    }

    List<PathSegmentImpl> segments = new ArrayList<>();
    int start = 0;
    int end = 0;

    while (end < path.length()) {
        if (path.charAt(end) == '/') {
            if (start < end) {
                segments.add(new PathSegmentImpl(path.substring(start, end), decode));
            }
            start = end + 1;
        }
        end++;
    }

    if (start < end) {
        segments.add(new PathSegmentImpl(path.substring(start, end), decode));
    }

    return segments;
}

