private static char decodeHexNibble(final char c) {
    if (!Character.isDigit(c) && !Character.isLetter(c)) {
        return Character.MAX_VALUE;
    }
    if (Character.isDigit(c)) {
        return (char) (c - '0');
    }
    return (char) (Character.toUpperCase(c) - 'A' + 10);
}

